import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"First Run Prompts","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-dev-guide/custom_build/first_run_prompts.md","filePath":"tr/qgc-dev-guide/custom_build/first_run_prompts.md"}`),a={name:`tr/qgc-dev-guide/custom_build/first_run_prompts.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="first-run-prompts" tabindex="-1">First Run Prompts <a class="header-anchor" href="#first-run-prompts" aria-label="Permalink to “First Run Prompts”">​</a></h1><p>When QGC is started for the first time it prompts the user to specify some initial settings. At the time of writing this documentation those are:</p><ul><li>Unit Settings - What units does the user want to use for display.</li><li>Offline Vehicle Settings - Vehicle information for creating Plans while not connected to a vehicle.</li></ul><p>The custom build architecure includes mechanisms for a custom build to both override the display of these prompts and/or create your own first run prompts.</p><h2 id="first-run-prompt-dialog" tabindex="-1">First Run Prompt Dialog <a class="header-anchor" href="#first-run-prompt-dialog" aria-label="Permalink to “First Run Prompt Dialog”">​</a></h2><p>Each first run prompt is a simple dialog which can display ui to the user. Whether the specific dialog has already been show to the user or not is stored in a setting. Here is the code for the upstream first run prompt dialogs:</p><ul><li><a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/FirstRunPromptDialogs/FirstRunPrompt.qml" target="_blank" rel="noreferrer">FirstRunPrompt</a> - base class</li><li><a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/FirstRunPromptDialogs/InitialSetupPrompt.qml" target="_blank" rel="noreferrer">InitialSetupPrompt</a> - units &amp; offline vehicle settings</li></ul><h2 id="standard-first-run-prompt-dialogs" tabindex="-1">Standard First Run Prompt Dialogs <a class="header-anchor" href="#standard-first-run-prompt-dialogs" aria-label="Permalink to “Standard First Run Prompt Dialogs”">​</a></h2><p>Each dialog has a unique ID associated with it. When that dialog is shown to the user that ID is registered as having already been displayed so it only happens once (unless you clear settings). The set of first run prompt which are included with upstream QGC are considered the &quot;Standard&quot; set. QGC gets the list of standard prompts to display from the <code>QGCCorePlugin::firstRunPromptStdIds</code> call.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    /// Returns the standard list of first run prompt ids for possible display. Actual display is based on the</span></span>
<span class="line"><span>    /// current AppSettings::firstRunPromptIds value. The order of this list also determines the order the prompts</span></span>
<span class="line"><span>    /// will be displayed in.</span></span>
<span class="line"><span>    virtual QList&lt;int&gt; firstRunPromptStdIds(void);</span></span></code></pre></div><p>You can override this method in your custom build if you want to hide some of those.</p><h2 id="custom-first-run-prompt-dialogs" tabindex="-1">Custom First Run Prompt Dialogs <a class="header-anchor" href="#custom-first-run-prompt-dialogs" aria-label="Permalink to “Custom First Run Prompt Dialogs”">​</a></h2><p>Custom builds have the ability to create their own set of additional first run prompts as needed through the use of the following QGCCorePlugin method overrides:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    /// Returns the custom build list of first run prompt ids for possible display. Actual display is based on the</span></span>
<span class="line"><span>    /// current AppSettings::firstRunPromptIds value. The order of this list also determines the order the prompts</span></span>
<span class="line"><span>    /// will be displayed in.</span></span>
<span class="line"><span>    virtual QList&lt;int&gt; firstRunPromptCustomIds(void);</span></span></code></pre></div><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    /// Returns the resource which contains the specified first run prompt for display</span></span>
<span class="line"><span>    Q_INVOKABLE virtual QString firstRunPromptResource(int id);</span></span></code></pre></div><p>Your QGCCorePlugin should override these two methods as well as provide static consts for the ids of your new first run prompts. Look at how the standard set is implemented for how to do this and take the same approach.</p><h2 id="order-of-display" tabindex="-1">Order Of Display <a class="header-anchor" href="#order-of-display" aria-label="Permalink to “Order Of Display”">​</a></h2><p>The set of first run prompts shown to the user are in the order returned by the <code>QGCCorePlugin::firstRunPromptStdIds</code> and <code>QGCCorePlugin::firstRunPromptCustomIds</code> with standard prompts shown before the custom prompts. Only the prompts which have not been previously shown to the user are shown.</p><h2 id="always-on-prompts" tabindex="-1">Always On Prompts <a class="header-anchor" href="#always-on-prompts" aria-label="Permalink to “Always On Prompts”">​</a></h2><p>By setting the <code>markAsShownOnClose: false</code> property in your prompt ui implementation you can create a prompt which will show up each time QGC starts. This can be used for things like showing usage tips to your users. If you do this it is best to make sure that this is displayed last.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};